import * as THREE from 'three';

// ============================================================
// Park geometry — one analytic height function drives BOTH the
// visual mesh and the physics, so what you see is what you ride.
// ============================================================
const PARK = 35;            // park half-size; walls at ±PARK
const QP_R = 9;             // quarter pipe radius
const GRAVITY = 22;

const FUNBOX = { x: 0, z: -8, h: 1.7, top: 3.2, ramp: 4.5 };
const KICKER = { x0: -22, x1: -15, z0: 9, z1: 14, h: 1.35 };  // launches you toward the rail
const RAIL = { z: 11.5, x0: -10, x1: 6, h: 1.05 };

function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

function groundHeight(x, z) {
  let h = 0;

  // Quarter pipes along the north and south walls
  const flat = PARK - QP_R;
  if (z < -flat) {
    const u = Math.min(-flat - z + (z < -PARK ? 0 : 0), QP_R); // distance into the transition
    const d = clamp(-z - flat, 0, QP_R);
    h = Math.max(h, QP_R - Math.sqrt(Math.max(QP_R * QP_R - d * d, 0)));
  } else if (z > flat) {
    const d = clamp(z - flat, 0, QP_R);
    h = Math.max(h, QP_R - Math.sqrt(Math.max(QP_R * QP_R - d * d, 0)));
  }

  // Funbox (pyramid with a flat top) in the middle of the park
  {
    const dx = Math.abs(x - FUNBOX.x);
    const dz = Math.abs(z - FUNBOX.z);
    const d = Math.max(dx, dz);
    h = Math.max(h, FUNBOX.h * clamp((FUNBOX.top + FUNBOX.ramp - d) / FUNBOX.ramp, 0, 1));
  }

  // Kicker ramp — rises toward +x then drops off a lip (sets up the rail grind)
  if (z >= KICKER.z0 && z <= KICKER.z1 && x >= KICKER.x0 && x <= KICKER.x1) {
    h = Math.max(h, KICKER.h * (x - KICKER.x0) / (KICKER.x1 - KICKER.x0));
  }

  return h;
}

function groundGradient(x, z) {
  const e = 0.18;
  return {
    x: (groundHeight(x + e, z) - groundHeight(x - e, z)) / (2 * e),
    z: (groundHeight(x, z + e) - groundHeight(x, z - e)) / (2 * e),
  };
}

// ============================================================
// Scene setup
// ============================================================
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x86b8e8);
scene.fog = new THREE.Fog(0x86b8e8, 60, 160);

const camera = new THREE.PerspectiveCamera(65, innerWidth / innerHeight, 0.1, 300);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

scene.add(new THREE.HemisphereLight(0xcfe8ff, 0x444a55, 0.9));
const sun = new THREE.DirectionalLight(0xfff2d9, 1.4);
sun.position.set(30, 50, 20);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -50; sun.shadow.camera.right = 50;
sun.shadow.camera.top = 50; sun.shadow.camera.bottom = -50;
sun.shadow.camera.far = 150;
scene.add(sun);

// --- Park surface: a displaced grid sampling groundHeight() ---
{
  const segs = 160;
  const geo = new THREE.PlaneGeometry(PARK * 2, PARK * 2, segs, segs);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const cLow = new THREE.Color(0x9aa0a8);   // flat concrete
  const cHigh = new THREE.Color(0xd8dde3);  // ramp tops
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const h = groundHeight(x, z);
    pos.setY(i, h);
    c.lerpColors(cLow, cHigh, clamp(h / QP_R, 0, 1) * 0.9 + ((Math.floor(x / 5) + Math.floor(z / 5)) % 2 === 0 ? 0.04 : 0));
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0.05 });
  const ground = new THREE.Mesh(geo, mat);
  ground.receiveShadow = true;
  scene.add(ground);
}

// --- Grind rail ---
{
  const railLen = RAIL.x1 - RAIL.x0;
  const railMat = new THREE.MeshStandardMaterial({ color: 0xffc94d, roughness: 0.3, metalness: 0.8 });
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, railLen, 12), railMat);
  bar.rotation.z = Math.PI / 2;
  bar.position.set((RAIL.x0 + RAIL.x1) / 2, RAIL.h, RAIL.z);
  bar.castShadow = true;
  scene.add(bar);
  for (const fx of [RAIL.x0 + 0.4, (RAIL.x0 + RAIL.x1) / 2, RAIL.x1 - 0.4]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, RAIL.h, 8), railMat);
    leg.position.set(fx, RAIL.h / 2, RAIL.z);
    scene.add(leg);
  }
}

// --- Fence around the park ---
{
  const fenceMat = new THREE.MeshStandardMaterial({ color: 0x3a4452, roughness: 0.9 });
  const mk = (w, d, x, z) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, 1.2, d), fenceMat);
    m.position.set(x, 0.6 + groundHeight(x, z) * 0, z);
    scene.add(m);
  };
  mk(PARK * 2 + 0.6, 0.3, 0, -PARK - 0.15);
  mk(PARK * 2 + 0.6, 0.3, 0, PARK + 0.15);
  mk(0.3, PARK * 2 + 0.6, -PARK - 0.15, 0);
  mk(0.3, PARK * 2 + 0.6, PARK + 0.15, 0);
  // Raise the fences behind the quarter pipes so they read as pipe backs
  for (const zส of []) {} // noop
  const backMat = new THREE.MeshStandardMaterial({ color: 0x46505e, roughness: 0.9 });
  for (const zSign of [-1, 1]) {
    const back = new THREE.Mesh(new THREE.BoxGeometry(PARK * 2, QP_R, 0.4), backMat);
    back.position.set(0, QP_R / 2, zSign * (PARK + 0.35));
    scene.add(back);
  }
}

// --- A few palm-ish trees outside for vibes ---
{
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8a6a4a });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f9e57 });
  const grass = new THREE.Mesh(
    new THREE.PlaneGeometry(400, 400),
    new THREE.MeshStandardMaterial({ color: 0x6aa86a, roughness: 1 })
  );
  grass.rotation.x = -Math.PI / 2;
  grass.position.y = -0.02;
  grass.receiveShadow = true;
  scene.add(grass);
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    const r = PARK + 8 + (i % 3) * 5;
    const t = new THREE.Group();
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.4, 5, 6), trunkMat);
    trunk.position.y = 2.5;
    const leaves = new THREE.Mesh(new THREE.ConeGeometry(2.2, 3.4, 7), leafMat);
    leaves.position.y = 6;
    t.add(trunk, leaves);
    t.position.set(Math.cos(a) * r, 0, Math.sin(a) * r);
    scene.add(t);
  }
}

// ============================================================
// Skater model — board is a sub-group so it can kickflip
// ============================================================
function makeNameSprite(name, colorHex) {
  const cv = document.createElement('canvas');
  cv.width = 256; cv.height = 64;
  const ctx = cv.getContext('2d');
  ctx.font = 'bold 34px Segoe UI, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 8;
  ctx.fillStyle = '#' + colorHex.toString(16).padStart(6, '0');
  ctx.fillText(name, 128, 32);
  const tex = new THREE.CanvasTexture(cv);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false }));
  sprite.scale.set(3, 0.75, 1);
  sprite.position.y = 2.6;
  return sprite;
}

function makeSkater(colorHex, name, withTag) {
  const g = new THREE.Group();

  const board = new THREE.Group();
  const deck = new THREE.Mesh(
    new THREE.BoxGeometry(0.42, 0.06, 1.5),
    new THREE.MeshStandardMaterial({ color: 0x2b2b2b, roughness: 0.6 })
  );
  deck.castShadow = true;
  const wheelMat = new THREE.MeshStandardMaterial({ color: 0xf5f0e6, roughness: 0.4 });
  for (const [wx, wz] of [[-0.16, 0.5], [0.16, 0.5], [-0.16, -0.5], [0.16, -0.5]]) {
    const w = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.07, 10), wheelMat);
    w.rotation.z = Math.PI / 2;
    w.position.set(wx, -0.11, wz);
    board.add(w);
  }
  board.add(deck);
  board.position.y = 0.2;
  g.add(board);

  const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.7 });
  const skinMat = new THREE.MeshStandardMaterial({ color: 0xe8b88a, roughness: 0.8 });
  const pantsMat = new THREE.MeshStandardMaterial({ color: 0x33363d, roughness: 0.9 });

  const rig = new THREE.Group();   // the person; crouches on ollie
  const legs = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.55, 0.26), pantsMat);
  legs.position.y = 0.55;
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.6, 0.3), bodyMat);
  torso.position.y = 1.12;
  torso.castShadow = true;
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 10), skinMat);
  head.position.y = 1.62;
  const armL = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.5, 0.11), bodyMat);
  armL.position.set(-0.3, 1.12, 0);
  const armR = armL.clone();
  armR.position.x = 0.3;
  rig.add(legs, torso, head, armL, armR);
  rig.position.y = 0.23;
  g.add(rig);

  if (withTag) g.add(makeNameSprite(name, colorHex));

  return { group: g, board, rig };
}

// ============================================================
// Local player physics + tricks
// ============================================================
const SPAWNS = [
  { x: 0, z: 20, ry: Math.PI },
  { x: -14, z: -18, ry: 0.4 },
  { x: 16, z: 4, ry: -Math.PI / 2 },
  { x: -24, z: 11.5, ry: Math.PI / 2 },
];

const me = {
  x: 0, y: 0, z: 20, ry: Math.PI,
  v: 0,                       // signed speed along facing direction
  vy: 0,
  grounded: true,
  airVX: 0, airVZ: 0,
  grinding: false,
  // trick state
  flipT: 0, spinT: 0, spinTotal: 0, grabbing: false, grabTime: 0,
  tricks: [],                 // names landed this air
  trickScore: 0,
  bailT: 0,
  score: 0,
};

let myModel = null;
const keys = {};
let chatOpen = false;

addEventListener('keydown', (e) => {
  if (chatOpen) return;
  keys[e.code] = true;
  if (e.code === 'Space') e.preventDefault();
  if (e.code === 'Enter') openChat();
  if (e.code === 'KeyR') respawn();
});
addEventListener('keyup', (e) => { keys[e.code] = false; });

function respawn() {
  const s = SPAWNS[Math.floor(Math.random() * SPAWNS.length)];
  me.x = s.x; me.z = s.z; me.ry = s.ry;
  me.y = groundHeight(s.x, s.z);
  me.v = 0; me.vy = 0;
  me.grounded = true; me.grinding = false; me.bailT = 0;
  resetAirTricks();
}

function resetAirTricks() {
  me.flipT = 0; me.spinT = 0; me.spinTotal = 0;
  me.grabbing = false; me.grabTime = 0;
  me.tricks = []; me.trickScore = 0;
}

function startAir() {
  me.grounded = false;
  const fx = Math.sin(me.ry), fz = Math.cos(me.ry);
  me.airVX = fx * me.v;
  me.airVZ = fz * me.v;
}

function tryStartGrind() {
  if (Math.abs(me.z - RAIL.z) < 0.8 &&
      me.x > RAIL.x0 && me.x < RAIL.x1 &&
      me.y > RAIL.h - 0.3 && me.y < RAIL.h + 0.9) {
    me.grinding = true;
    me.grindDir = me.airVX >= 0 ? 1 : -1;
    me.grindSpeed = Math.max(Math.abs(me.airVX), 4);
    me.z = RAIL.z;
    me.y = RAIL.h;
    me.vy = 0;
    me.ry = me.grindDir > 0 ? Math.PI / 2 : -Math.PI / 2;
    showBanner('GRIND!');
    return true;
  }
  return false;
}

function land() {
  me.grounded = true;
  me.vy = 0;
  // bail if a flip or spin was still mid-rotation
  const midTrick = me.flipT > 0 || me.spinT > 0;
  if (midTrick) {
    me.bailT = 1.1;
    me.v *= 0.25;
    showBanner('BAILED!', '#ff6b6b');
    resetAirTricks();
    return;
  }
  if (me.grabbing) {
    me.tricks.push('Grab');
    me.trickScore += Math.round(me.grabTime * 60);
  }
  if (me.tricks.length > 0) {
    const bonus = me.tricks.length > 1 ? me.tricks.length : 1; // combo multiplier
    const pts = me.trickScore * bonus;
    me.score += pts;
    const label = me.tricks.join(' + ') + (bonus > 1 ? ` x${bonus}` : '');
    showBanner(`${label}  +${pts}`);
    net.sendTrick(label, pts);
    updateScoreHud();
  }
  // direction snaps to travel direction on landing
  const sp = Math.hypot(me.airVX, me.airVZ);
  if (sp > 0.5) {
    me.ry = Math.atan2(me.airVX, me.airVZ);
    me.v = sp;
  }
  resetAirTricks();
}

function stepPlayer(dt) {
  if (me.bailT > 0) {
    me.bailT -= dt;
    me.v *= 1 - 2.5 * dt;
    const gh = groundHeight(me.x, me.z);
    me.y = gh;
    return;
  }

  if (me.grinding) {
    me.x += me.grindDir * me.grindSpeed * dt;
    me.grindScoreAcc = (me.grindScoreAcc || 0) + 30 * dt;
    if (keys['Space'] || me.x <= RAIL.x0 || me.x >= RAIL.x1) {
      const pts = Math.round(me.grindScoreAcc);
      me.grindScoreAcc = 0;
      if (pts > 5) {
        me.score += pts;
        showBanner(`Rail Grind  +${pts}`);
        net.sendTrick('Rail Grind', pts);
        updateScoreHud();
      }
      me.grinding = false;
      me.v = me.grindDir * me.grindSpeed;
      me.vy = keys['Space'] ? 7.5 : 2;
      startAir();
      me.vy = keys['Space'] ? 7.5 : 2;
      me.airVX = me.grindDir * me.grindSpeed;
      me.airVZ = 0;
      me.ry = Math.atan2(me.airVX, me.airVZ);
    }
    return;
  }

  if (me.grounded) {
    // steering
    const turn = 2.6 * (me.v >= 0 ? 1 : -1) * clamp(Math.abs(me.v) / 6 + 0.35, 0, 1);
    if (keys['KeyA'] || keys['ArrowLeft']) me.ry += turn * dt;
    if (keys['KeyD'] || keys['ArrowRight']) me.ry -= turn * dt;

    // push / brake
    if (keys['KeyW'] || keys['ArrowUp']) me.v += 9 * dt;
    if (keys['KeyS'] || keys['ArrowDown']) me.v -= 12 * dt;
    me.v = clamp(me.v, -6, 19);

    // slope pulls you downhill (this is what makes pipes feel right)
    const grad = groundGradient(me.x, me.z);
    const fx = Math.sin(me.ry), fz = Math.cos(me.ry);
    me.v -= GRAVITY * (grad.x * fx + grad.z * fz) * dt * 0.55;

    // rolling friction
    me.v *= 1 - 0.35 * dt;

    // move
    const prevY = me.y;
    me.x += fx * me.v * dt;
    me.z += fz * me.v * dt;
    clampToPark();
    const gh = groundHeight(me.x, me.z);
    const terrainVy = (gh - prevY) / dt;

    if (keys['Space']) {
      // ollie — extra pop if you're already moving up a transition
      me.vy = 7.5 + Math.max(terrainVy * 0.45, 0);
      startAir();
      me.y = prevY;
    } else if (terrainVy < me.vy - 30 * dt && me.vy > 3.5) {
      // ground fell away while we were moving up fast: launched off a lip
      startAir();
      me.y = prevY;
    } else {
      me.y = gh;
      me.vy = terrainVy;
    }
  }

  if (!me.grounded && !me.grinding) {
    me.vy -= GRAVITY * dt;
    me.x += me.airVX * dt;
    me.z += me.airVZ * dt;
    me.y += me.vy * dt;
    clampToPark(true);

    // air tricks
    if (keys['KeyJ'] && me.flipT <= 0 && !me.tricks.includes('Kickflip')) {
      me.flipT = 0.45;
    }
    if (keys['KeyK'] && me.spinT <= 0 && me.spinTotal === 0) {
      me.spinT = 0.65;
    }
    me.grabbing = !!keys['KeyL'];
    if (me.grabbing) me.grabTime += dt;

    if (me.flipT > 0) {
      me.flipT -= dt;
      if (me.flipT <= 0) { me.flipT = 0; me.tricks.push('Kickflip'); me.trickScore += 100; }
    }
    if (me.spinT > 0) {
      me.spinT -= dt;
      me.spinTotal += (Math.PI * 2 / 0.65) * dt;
      if (me.spinT <= 0) {
        me.spinT = 0; me.spinTotal = 0;
        me.tricks.push('360 Spin'); me.trickScore += 150;
      }
    }

    const gh = groundHeight(me.x, me.z);
    if (me.vy < 0 && tryStartGrind()) return;
    if (me.y <= gh) {
      me.y = gh;
      land();
    }
  }
}

function clampToPark(air = false) {
  const lim = PARK - 0.8;
  if (me.x < -lim || me.x > lim) { me.x = clamp(me.x, -lim, lim); if (air) me.airVX *= -0.4; else me.v *= 0.3; }
  if (me.z < -lim || me.z > lim) { me.z = clamp(me.z, -lim, lim); if (air) me.airVZ *= -0.4; else me.v *= 0.3; }
}

// visual pose for any skater (local or remote) from a state snapshot
function poseModel(model, s, dt) {
  model.group.position.set(s.x, s.y, s.z);
  model.group.rotation.y = s.ry + (s.spin || 0);
  model.board.rotation.x = s.flip || 0;
  // crouch when grabbing, slight crouch when bailed
  const crouch = s.grab ? 0.35 : (s.bail ? 0.5 : 0);
  model.rig.scale.y = 1 - crouch * 0.55;
  model.rig.rotation.x = s.grab ? 0.35 : 0;
  model.group.rotation.z = s.grab ? 0.25 : 0;
}

function myVisualState() {
  return {
    x: me.x, y: me.y, z: me.z, ry: me.ry,
    spin: me.spinTotal,
    flip: me.flipT > 0 ? (1 - me.flipT / 0.45) * Math.PI * 2 : 0,
    grab: me.grabbing,
    bail: me.bailT > 0,
  };
}

// ============================================================
// HUD
// ============================================================
const bannerEl = document.getElementById('trick-banner');
let bannerTimer = null;
function showBanner(text, color = '#ffd24d') {
  bannerEl.textContent = text;
  bannerEl.style.color = color;
  bannerEl.style.opacity = '1';
  clearTimeout(bannerTimer);
  bannerTimer = setTimeout(() => { bannerEl.style.opacity = '0'; }, 1600);
}

const scoreEl = document.getElementById('score');
const comboEl = document.getElementById('combo');
function updateScoreHud() {
  scoreEl.textContent = me.score.toLocaleString();
  updateLeaderboard();
}

const lbEl = document.getElementById('lb-rows');
function updateLeaderboard() {
  const rows = [{ name: myName + ' (you)', color: myColor, score: me.score }];
  for (const p of remotes.values()) rows.push({ name: p.name, color: p.color, score: p.score });
  rows.sort((a, b) => b.score - a.score);
  lbEl.innerHTML = rows.map(r =>
    `<div class="row"><span><span class="dot" style="background:#${r.color.toString(16).padStart(6, '0')}"></span>${escapeHtml(r.name)}</span><span>${r.score.toLocaleString()}</span></div>`
  ).join('');
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// --- chat ---
const chatLog = document.getElementById('chat-log');
const chatInput = document.getElementById('chat-input');
function addChat(html, cls = '') {
  const div = document.createElement('div');
  if (cls) div.className = cls;
  div.innerHTML = html;
  chatLog.appendChild(div);
  while (chatLog.children.length > 10) chatLog.removeChild(chatLog.firstChild);
  chatLog.scrollTop = chatLog.scrollHeight;
}
function openChat() {
  chatOpen = true;
  chatInput.style.display = 'block';
  setTimeout(() => chatInput.focus(), 0);
}
function closeChat() {
  chatOpen = false;
  chatInput.value = '';
  chatInput.style.display = 'none';
  chatInput.blur();
}
chatInput.addEventListener('keydown', (e) => {
  e.stopPropagation();
  if (e.code === 'Escape') closeChat();
  if (e.code === 'Enter') {
    const text = chatInput.value.trim();
    if (text) {
      net.sendChat(text);
      addChat(`<b style="color:#${myColor.toString(16).padStart(6, '0')}">${escapeHtml(myName)}:</b> ${escapeHtml(text)}`);
    }
    closeChat();
  }
});

// ============================================================
// Networking
// ============================================================
const remotes = new Map(); // id -> { name, color, score, model, target, cur }
let myName = 'Skater';
let myColor = 0xffffff;
let ws = null;

const net = {
  send(msg) { if (ws && ws.readyState === 1) ws.send(JSON.stringify(msg)); },
  sendTrick(name, score) { this.send({ t: 'trick', name, score }); },
  sendChat(text) { this.send({ t: 'chat', text }); },
};

function addRemote(id, name, color, state) {
  const model = makeSkater(color, name, true);
  scene.add(model.group);
  const s = state || { x: 0, y: 0, z: 20, ry: 0 };
  remotes.set(id, { name, color, score: 0, model, target: { ...s }, cur: { ...s } });
  updateLeaderboard();
}

function removeRemote(id) {
  const p = remotes.get(id);
  if (p) {
    scene.remove(p.model.group);
    remotes.delete(id);
    addChat(`${escapeHtml(p.name)} left the park`, 'sys');
    updateLeaderboard();
  }
}

function connect(name) {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  ws = new WebSocket(`${proto}://${location.host}`);
  const status = document.getElementById('conn-status');

  ws.onopen = () => net.send({ t: 'join', name });

  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    switch (msg.t) {
      case 'welcome':
        myColor = msg.color;
        for (const p of msg.players) addRemote(p.id, p.name, p.color, p.state);
        startGame();
        break;
      case 'joined':
        addRemote(msg.id, msg.name, msg.color);
        addChat(`${escapeHtml(msg.name)} dropped in!`, 'sys');
        break;
      case 'left':
        removeRemote(msg.id);
        break;
      case 'state': {
        const p = remotes.get(msg.id);
        if (p) p.target = msg.s;
        break;
      }
      case 'trick': {
        const p = remotes.get(msg.id);
        if (p) {
          p.score += msg.score;
          addChat(`<span style="color:#${p.color.toString(16).padStart(6, '0')}">${escapeHtml(p.name)}</span> landed <b>${escapeHtml(msg.name)}</b> +${msg.score}`, 'sys');
          updateLeaderboard();
        }
        break;
      }
      case 'chat': {
        const p = remotes.get(msg.id);
        const col = p ? p.color : 0xffffff;
        addChat(`<b style="color:#${col.toString(16).padStart(6, '0')}">${escapeHtml(msg.from)}:</b> ${escapeHtml(msg.text)}`);
        break;
      }
    }
  };

  ws.onclose = () => {
    status.textContent = 'Disconnected from server.';
    addChat('Disconnected from server — refresh to rejoin.', 'sys');
  };
  ws.onerror = () => {
    status.textContent = 'Could not reach the server. Is it running?';
  };
}

// send my state ~15 times per second
setInterval(() => {
  if (ws && ws.readyState === 1 && running) {
    const s = myVisualState();
    // round to keep packets small
    for (const k of ['x', 'y', 'z', 'ry', 'spin', 'flip']) s[k] = Math.round(s[k] * 100) / 100;
    net.send({ t: 'state', s });
  }
}, 66);

// ============================================================
// Camera + main loop
// ============================================================
const camPos = new THREE.Vector3(0, 6, 30);
function updateCamera(dt) {
  const fx = Math.sin(me.ry), fz = Math.cos(me.ry);
  const want = new THREE.Vector3(me.x - fx * 7.5, me.y + 3.6, me.z - fz * 7.5);
  // keep the camera above the terrain
  want.y = Math.max(want.y, groundHeight(want.x, want.z) + 1.4);
  camPos.lerp(want, 1 - Math.pow(0.0015, dt));
  camera.position.copy(camPos);
  camera.lookAt(me.x, me.y + 1.4, me.z);
}

let running = false;
let lastT = performance.now();

function loop(now) {
  requestAnimationFrame(loop);
  const dt = Math.min((now - lastT) / 1000, 0.05);
  lastT = now;
  if (!running) return;

  stepPlayer(dt);
  poseModel(myModel, myVisualState(), dt);

  // interpolate remote players toward their latest snapshot
  for (const p of remotes.values()) {
    const k = 1 - Math.pow(0.0001, dt);
    const c = p.cur, t = p.target;
    c.x += (t.x - c.x) * k;
    c.y += (t.y - c.y) * k;
    c.z += (t.z - c.z) * k;
    let dr = (t.ry - c.ry) % (Math.PI * 2);
    if (dr > Math.PI) dr -= Math.PI * 2;
    if (dr < -Math.PI) dr += Math.PI * 2;
    c.ry += dr * k;
    c.spin = t.spin || 0;
    c.flip = t.flip || 0;
    c.grab = t.grab;
    c.bail = t.bail;
    poseModel(p.model, c, dt);
  }

  updateCamera(dt);
  renderer.render(scene, camera);
}
requestAnimationFrame(loop);

function startGame() {
  myModel = makeSkater(myColor, myName, false);
  scene.add(myModel.group);
  respawn();
  updateScoreHud();
  document.getElementById('join-overlay').style.display = 'none';
  addChat('Welcome to the park! Press Enter to chat.', 'sys');
  running = true;
}

